// Preset: full-stack
export const capabilities = [
  'views',
  'admin',
  'api',
  'auth',
  'content',
  'database'
] as const;

export const config = {
  database: 'pglite',
  driver: '@electric-sql/pglite'
};

import type { HttpServer } from 'stackpress/http';

export default function admin(server: HttpServer) {
  server.get('/admin', ({ res }) => {
    res.set('text/plain', 'stackpress-app admin');
  });
}

import type { HttpServer } from 'stackpress/http';

export default function api(server: HttpServer) {
  server.get('/api', ({ res }) => {
    res.set('application/json', JSON.stringify({ preset: 'full-stack' }));
  });
}

import type { HttpServer } from 'stackpress/http';

export default function app(server: HttpServer) {
  server.get('/', ({ res }) => {
    res.set('text/plain', 'Hello from stackpress-app');
  });
}

import type { HttpServer } from 'stackpress/http';

export default function auth(server: HttpServer) {
  server.get('/auth', ({ res }) => {
    res.set('text/plain', 'auth enabled for stackpress-app');
  });
}

// Database: pglite
// Adapter: @stackpress/inquire-pglite
// Driver: @electric-sql/pglite
export const database = 'pglite';
export const adapter = '@stackpress/inquire-pglite';
export const driver = '@electric-sql/pglite';

export default async function connect() {
  return { database, adapter, driver };
}

export default function Home() {
  return <main>stackpress-app home page</main>;
}

